import { requireChapter } from "../../lab/syllabus";
import { CodeBlock } from "../code-block";
import { DemoSection } from "../demo-section";
import { InlineCode } from "../inline-code";
import { ReferenceBar } from "../reference-bar";
import { BoundaryPanel } from "./boundary-panel";
import { ServerCard } from "./server-card";
import { BOUNDARY_SOURCE } from "./source";

const chapter = requireChapter("boundary");

interface BoundaryDemoProps {
  headingAs?: "h1" | "h2";
}

export function BoundaryDemo({ headingAs }: BoundaryDemoProps) {
  return (
    <DemoSection
      belief={chapter.belief}
      headingAs={headingAs}
      id={`demo-${chapter.slug}`}
      intro={
        <>
          <p>
            They can — and most of yours already do. Every component in the App
            Router starts on the server, which means it can read the database,
            hold the API key, and finish its work before it ever reaches your
            visitor. <InlineCode>&quot;use client&quot;</InlineCode>
            &#32;is how you spend that: you trade the database call and the key
            for useState, useEffect and onClick, for that file and everything it
            imports. It is a good trade. It is just not a free one.
          </p>
          <p>
            The card below is a Server Component — no directive, because that is
            the default. It fetched this repo&rsquo;s latest commit in Node.js
            and arrived as finished HTML; the component that made it is already
            gone. Use the deck to give the hash a copy button and the compiler
            steps in with the exact fix, by name. Apply it and the compiler
            steps in again — the directive claimed the whole file, and &quot;use
            cache&quot; has no client form — and names the real fix: a separate
            file. Take the third step and the button works. Three moves, every
            one of them signposted.
          </p>
        </>
      }
      meta={
        <>
          The line is the boundary that lets data through. In the final state
          the hash crosses it as a prop to the button — serialized, one way,
          server to client. Capability stays put: the fetch never crosses, only
          what it fetched.
        </>
      }
      navLabel={chapter.navLabel}
      topic={chapter.topic}
    >
      {/* The client panel owns the instrument: the beat is its view state,
          and the server card crosses into it as a finished slot — the
          composition the chapter teaches, load-bearing in its own frame. */}
      <BoundaryPanel
        references={
          <ReferenceBar
            docsHref="https://nextjs.org/docs/app/getting-started/server-and-client-components"
            sourceHref="https://github.com/hasToggle/hasToggle.dev/tree/main/apps/web/app/%5Blocale%5D/(playground)/boundary"
          >
            <CodeBlock
              code={BOUNDARY_SOURCE}
              file="card.tsx · start, crossed, split"
            />
          </ReferenceBar>
        }
        serverCard={<ServerCard />}
        splitCard={<ServerCard withButton />}
      />
    </DemoSection>
  );
}
