/**
 * Every string the boundary instrument shows, in the instrument register:
 * lowercase, middot-separated, mechanism facts only. The panel never
 * narrates its own construction (design.md §4, 2026-08-27) — each line
 * states something about where components run, not about how this demo
 * manages to show it.
 *
 * Prose strings carry typographic marks directly (voice.md §8); anything
 * quoting real code keeps straight quotes.
 */

/** The instrument's two states, in the order the deck walks them. */
export type Beat = "rest" | "split";

/** The file's first line, worn on the card the way a file wears it. */
export const DIRECTIVE_LINES: Record<Beat, string> = {
  rest: "// no directive",
  split: "// no directive",
};

/** Which side of the boundary card.tsx itself is on, for the badge. */
export const SIDES: Record<Beat, "client" | "server"> = {
  rest: "server",
  split: "server",
};

/** The rows under the card: what the server side can do, then where the button went. */
export const FACTS: Record<Beat, readonly string[]> = {
  rest: [
    "runs in Node: databases, secrets, the filesystem",
    "ships 0 kB of JavaScript",
    "renders once, returns HTML, and is gone",
  ],
  split: [
    '"use client" sits in copy-button.tsx — one directive, one small file',
    "the fetch stayed in Node.js — cached once, served to everyone",
    "shipped to the browser: the button, and only the button",
  ],
};

/** The seam under the card — the one fact each state proves. */
export const SEAMS: Record<Beat, string> = {
  rest: "the dashed line is where this file lives · the server, like every file that doesn’t say otherwise",
  split:
    "a Server Component can import a Client Component · the directive sits on the smallest file that needs it",
};

/** The deck's one step: the change the hash itself asks for. */
export const STEP_LABEL = "Add a copy button";
export const STEP_DETAIL = "copy-button.tsx";

/** Chrome, top-right: instrument housekeeping, disabled at rest. */
export const RESET_LABEL = "reset";

import { describe, expect, test } from "bun:test";
import {
  DIRECTIVE_LINES,
  FACTS,
  SEAMS,
  SIDES,
  STEP_DETAIL,
  STEP_LABEL,
} from "./copy";

const BEATS = ["rest", "split"] as const;

describe("the beats", () => {
  test("card.tsx never carries the directive — the button's file does", () => {
    expect(DIRECTIVE_LINES.rest).toBe("// no directive");
    expect(DIRECTIVE_LINES.split).toBe("// no directive");
  });

  test("card.tsx stays on the server in both states", () => {
    expect(SIDES.rest).toBe("server");
    expect(SIDES.split).toBe("server");
  });

  test("the split names the file that carries the directive", () => {
    expect(FACTS.split[0]).toContain(STEP_DETAIL);
    expect(FACTS.split[0]).toContain('"use client"');
    expect(SEAMS.split).toContain("Client Component");
  });

  test("the rest state lists what the server side can do", () => {
    expect(FACTS.rest[0]).toContain("Node");
    expect(FACTS.rest[1]).toContain("0 kB");
  });

  test("every beat carries three fact rows and a seam", () => {
    for (const beat of BEATS) {
      expect(FACTS[beat]).toHaveLength(3);
      expect(SEAMS[beat].length).toBeGreaterThan(0);
    }
  });
});

describe("register (voice.md §8)", () => {
  test("prose apostrophes are typographic", () => {
    for (const beat of BEATS) {
      for (const line of [...FACTS[beat], SEAMS[beat]]) {
        expect(line).not.toContain("'");
      }
    }
  });

  test("the deck step is a subject action with its file as detail", () => {
    expect(STEP_LABEL).toBe("Add a copy button");
    expect(STEP_DETAIL).toBe("copy-button.tsx");
  });
});

/**
 * The drawer shows the file at both of the instrument's states — the
 * Server Component as it started, then the same file importing the one
 * small client file the button needed. Condensed the way every drawer
 * here condenses: real API, real shapes, the layout noise left out.
 */
export const BOUNDARY_SOURCE = `// card.tsx — as it started. No directive: a Server Component,
// like every file that doesn't say otherwise.
import { cacheLife } from "next/cache";

async function getLatestCommit() {
  "use cache";
  cacheLife("hours");
  const response = await fetch(
    "https://api.github.com/repos/hasToggle/hasToggle.dev/commits/main"
  );
  const { sha, commit } = await response.json();
  return { sha: sha.slice(0, 7), subject: commit.message.split("\\n")[0] };
}

export async function Card() {
  const { sha, subject } = await getLatestCommit();
  return <p>latest commit {sha} — {subject}</p>;
}

// card.tsx — with the copy button. Still no directive: the fetch never
// left Node, and the one file that needs the browser carries its own line.
import { CopyButton } from "./copy-button";

export async function Card() {
  const { sha, subject } = await getLatestCommit();
  return <p>latest commit {sha} <CopyButton value={sha} /></p>;
}

// copy-button.tsx — the entire client bundle of this card.
"use client";
import { useState } from "react";

export function CopyButton({ value }) {
  const [copied, setCopied] = useState(false);
  return (
    <button onClick={() => {
      navigator.clipboard.writeText(value);
      setCopied(true);
    }}>
      {copied ? "copied" : "copy"}
    </button>
  );
}`;

"use client";

import { cn } from "@repo/design-system/lib/utils";
import { useCallback, useState } from "react";
import { MarketingButton } from "../../components/marketing-button";
import { LivePanel } from "../live-panel";
import { FileCard } from "./card";
import type { Beat } from "./copy";
import { RESET_LABEL, SEAMS, STEP_DETAIL, STEP_LABEL } from "./copy";

// The outline variant's `disabled:` look re-expressed for `aria-disabled`,
// so the spent step stays focusable and keyboard users keep their place.
// Same trick as the rebake deck.
const LOCKED_LOOK = cn(
  "aria-disabled:bg-transparent aria-disabled:opacity-40",
  "aria-disabled:cursor-not-allowed aria-disabled:hover:bg-transparent"
);

// The nudge: while the step is pressable it wears the boundary's own
// orange on its ring, so the hand knows where the sequence starts.
const ARMED_LOOK = "ring-ht-orange-700/50 dark:ring-ht-orange-500/50";

/** Ghost-stack order for height reservation. */
const ALL_BEATS: readonly Beat[] = ["rest", "split"];

interface BoundaryPanelProps {
  references: React.ReactNode;
  /**
   * The rest beat's body, rendered on the server and handed across the
   * boundary as a finished slot — a client component cannot render a
   * Server Component, only be handed one.
   */
  serverCard: React.ReactNode;
  /**
   * The split beat's body: the same Server Component, now importing the
   * copy-button client island. Also server-rendered, also a slot.
   */
  splitCard: React.ReactNode;
}

/**
 * The client owner of the boundary instrument. The gauge stays `live`:
 * nothing here makes a server round trip — both server slots arrived with
 * the page, and the step between them is a client render.
 *
 * Two states: a Server Component doing the work developers expect of one,
 * then the same component with a copy button — which lands in its own
 * file, inside its own line, while the fetch stays where it was. Reset is
 * instrument housekeeping, not a subject action, so it sits in the chrome
 * and stays locked at rest (design.md §4, 2026-08-27).
 */
export function BoundaryPanel({
  references,
  serverCard,
  splitCard,
}: BoundaryPanelProps) {
  const [beat, setBeat] = useState<Beat>("rest");

  const handleReset = useCallback(() => setBeat("rest"), []);
  const handleStep = useCallback(() => setBeat("split"), []);

  const viewControls = (
    <button
      aria-disabled={beat === "rest"}
      className={cn(
        "cursor-pointer select-none font-mono font-semibold text-[0.7rem] text-muted-foreground uppercase tracking-[0.2em] hover:text-foreground",
        "aria-disabled:cursor-default aria-disabled:opacity-40 aria-disabled:hover:text-muted-foreground"
      )}
      onClick={handleReset}
      type="button"
    >
      {RESET_LABEL} <span aria-hidden="true">↺</span>
    </button>
  );

  const deck = (
    <div className="flex flex-wrap items-center gap-3">
      <MarketingButton
        aria-disabled={beat !== "rest"}
        className={cn(LOCKED_LOOK, beat === "rest" && ARMED_LOOK)}
        onClick={handleStep}
        variant="outline"
      >
        {STEP_LABEL}
        <span className="ml-2 font-mono text-muted-foreground text-xs">
          {STEP_DETAIL}
        </span>
      </MarketingButton>
    </div>
  );

  return (
    <LivePanel deck={deck} references={references} viewControls={viewControls}>
      <div className="flex flex-col gap-5">
        {/* Both cards stacked in one grid cell, the inactive one invisible
            but still holding its space — so the instrument is always as
            tall as its taller beat and the deck never moves. Same
            reservation trick as the rebake panel's StableSlot, at card
            scale. The active wrapper's key flips on activation, so the
            split card's landing wash (.ht-land) replays on each arrival. */}
        <div className="grid">
          {ALL_BEATS.map((b) => {
            const active = b === beat;
            return (
              <div
                aria-hidden={!active}
                className={cn(
                  "[grid-area:1/1]",
                  active ? b === "split" && "ht-land" : "invisible"
                )}
                key={`${b}-${active}`}
              >
                <FileCard beat={b}>
                  {b === "rest" ? serverCard : splitCard}
                </FileCard>
              </div>
            );
          })}
        </div>
        {/* The seam, narrated: the one fact the current beat proves. The
            ghost reserves the taller seam's height for the same reason. */}
        <p
          className="grid font-mono text-muted-foreground text-xs/5"
          role="status"
        >
          {ALL_BEATS.map((b) => (
            <span
              aria-hidden={b !== beat}
              className={cn("[grid-area:1/1]", b !== beat && "invisible")}
              key={b}
            >
              {SEAMS[b]}
            </span>
          ))}
        </p>
      </div>
    </LivePanel>
  );
}

import { requireChapter } from "../../lab/syllabus";
import { CodeBlock } from "../code-block";
import { DemoSection } from "../demo-section";
import { InlineCode } from "../inline-code";
import { ReferenceBar } from "../reference-bar";
import { BoundaryPanel } from "./boundary-panel";
import { ServerCard } from "./server-card";
import { BOUNDARY_SOURCE } from "./source";

const chapter = requireChapter("boundary");

interface BoundaryDemoProps {
  headingAs?: "h1" | "h2";
}

export function BoundaryDemo({ headingAs }: BoundaryDemoProps) {
  return (
    <DemoSection
      headingAs={headingAs}
      id={`demo-${chapter.slug}`}
      intro={
        <>
          <p>
            They can, and most of yours already do. Every component in the App
            Router starts on the server, so it can call the API, read the
            database, hold the key, and finish its work before the page
            reaches your visitor. The browser gets the result, not the work.
            &#32;<InlineCode>&quot;use client&quot;</InlineCode>&#32;marks the
            one file that needs the browser, and that file is usually small.
          </p>
          <p>
            The component below fetched this repo&rsquo;s latest commit in
            Node.js and arrived as finished HTML. Add a copy button to the
            hash and watch where it lands: in its own file, inside its own
            line. The fetch never moves. The button is the only thing that
            ships.
          </p>
        </>
      }
      meta={
        <>
          The line is the boundary that lets data through. The hash crosses
          it as a prop to the button — serialized, one way, server to client.
          The fetch never crosses, only what it fetched.
        </>
      }
      navLabel={chapter.navLabel}
      title={chapter.title}
      topic={chapter.topic}
    >
      {/* The client panel owns the instrument: the beat is its view state,
          and the server card crosses into it as a finished slot — the
          composition the chapter teaches, load-bearing in its own frame. */}
      <BoundaryPanel
        references={
          <ReferenceBar
            docsHref="https://nextjs.org/docs/app/getting-started/server-and-client-components"
            sourceHref="https://github.com/hasToggle/hasToggle.dev/tree/main/apps/web/app/%5Blocale%5D/(playground)/boundary"
          >
            <CodeBlock code={BOUNDARY_SOURCE} file="card.tsx · before, after" />
          </ReferenceBar>
        }
        serverCard={<ServerCard />}
        splitCard={<ServerCard withButton />}
      />
    </DemoSection>
  );
}

